/**
 * CAPS WORD KEY RULES (firmware.capsWordRules): which keys keep Caps Word on and which of them it shifts, on every layer
 * or only on some. Unset = QMK's own list (CAPS_WORD_QMK_DEFAULT is that list, what the UI fills in when the rules are
 * turned on). The C is generated by core/qmk/capsWord.ts.
 *
 * For a key: the rules with layers come first (in list order), then the first every-layer rule. A layer rule counts when
 * the highest active layer is one of its layers. No match: the key ends Caps Word.
 */
import type { AdvancedIssue } from '../features/advanced';
import { toQmk } from '../keycodes/codec';
import { loadSpec } from '../keycodes/spec';
import type { CapsWordRule, Project } from './types';

export const CAPS_WORD_RULES_MAX = 32;
export const CAPS_WORD_KEYS_MAX = 128;

/** Basic keycode values (HID usage ids) QMK's default list is made of. */
const KC_A = 0x04;
const KC_1 = 0x1e;
const KC_BSPC = 0x2a;
const KC_MINS = 0x2d;
const KC_DEL = 0x4c;
const MOD_LSFT = 0x0200;

/** QMK's own list: letters and minus are shifted; digits, Backspace, Delete and underscore keep Caps Word on. */
export const CAPS_WORD_QMK_DEFAULT: CapsWordRule[] = [
  { id: 'qmk-shift', keys: [...Array.from({ length: 26 }, (_, i) => KC_A + i), KC_MINS], shift: true },
  { id: 'qmk-keep', keys: [...Array.from({ length: 10 }, (_, i) => KC_1 + i), KC_BSPC, KC_DEL, MOD_LSFT | KC_MINS], shift: false },
];

/** A rule's keys with its key lists' keys, each once. */
export function capsWordRuleKeys(project: Pick<Project, 'keyLists'>, rule: CapsWordRule): number[] {
  const out = new Set(rule.keys);
  for (const id of rule.lists ?? []) for (const k of project.keyLists.find((l) => l.id === id)?.keys ?? []) out.add(k);
  return [...out];
}

/** Rules whose layers are unset or empty count on every layer. */
export const capsWordEveryLayer = (r: CapsWordRule) => !r.layers?.length;

const sharesLayers = (a: CapsWordRule, b: CapsWordRule) =>
  capsWordEveryLayer(a) ? capsWordEveryLayer(b) : !capsWordEveryLayer(b) && a.layers!.some((l) => b.layers!.includes(l));

export function checkCapsWordRules(project: Project): AdvancedIssue[] {
  const rules = project.firmware.capsWordRules;
  if (!rules) return [];
  const spec = loadSpec('latest');
  const out: AdvancedIssue[] = [];
  const keyName = (v: number) => toQmk(spec, v, {});
  if (rules.length > CAPS_WORD_RULES_MAX) {
    out.push({ level: 'error', where: 'caps word', message: { en: `At most ${CAPS_WORD_RULES_MAX} rules.`, ru: `Не больше ${CAPS_WORD_RULES_MAX} правил.` } });
  }
  const expanded = rules.map((r) => capsWordRuleKeys(project, r));
  rules.forEach((r, i) => {
    const where = 'caps word';
    const n = `Rule ${i + 1}: `;
    const nr = `Правило ${i + 1}: `;
    if (r.keys.length === 0 && !r.lists?.length) {
      out.push({ level: 'warning', where, message: { en: `${n}this rule has no keys: it does nothing.`, ru: `${nr}в этом правиле нет клавиш: оно ничего не делает.` } });
    }
    for (const id of r.lists ?? []) {
      if (!project.keyLists.some((l) => l.id === id)) {
        out.push({ level: 'warning', where, message: { en: `${n}points to a key list that no longer exists.`, ru: `${nr}ссылается на список клавиш, которого больше нет.` } });
      }
    }
    if (expanded[i].length > CAPS_WORD_KEYS_MAX) {
      out.push({ level: 'error', where, message: { en: `${n}at most ${CAPS_WORD_KEYS_MAX} keys in a rule.`, ru: `${nr}не больше ${CAPS_WORD_KEYS_MAX} клавиш в правиле.` } });
    }
    for (const k of expanded[i]) {
      if (rules.some((e, j) => j < i && sharesLayers(e, r) && expanded[j].includes(k))) {
        out.push({
          level: 'warning',
          where,
          message: {
            en: `${n}${keyName(k)} is already in an earlier rule for the same layers: only that one counts.`,
            ru: `${nr}${keyName(k)} уже есть в более раннем правиле для тех же слоёв: считается только оно.`,
          },
        });
      }
    }
  });
  return out;
}
